package io.github.diodeme.ji.session.jsonl;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.session.codec.json.JacksonSessionCodec;
import io.github.diodeme.ji.session.tree.SessionDocument;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.function.UnaryOperator;

/** Crash-safe JSONL repository. Each line is a complete canonical revision; the final valid line is authoritative. */
public final class JsonlSessionRepository implements SessionRepository {
    private static final String SUFFIX = ".jsonl";
    private final Path root;
    private final JacksonSessionCodec codec = new JacksonSessionCodec();
    private final ObjectMapper lines = new ObjectMapper();

    public JsonlSessionRepository(Path root) {
        this.root = root.toAbsolutePath().normalize();
        try {
            Files.createDirectories(this.root);
        } catch (IOException exception) {
            throw storage("cannot create JSONL Session root", exception);
        }
    }

    @Override
    public synchronized SessionDocument create(String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        Path target = path(sessionId);
        if (Files.exists(target)) throw new IllegalStateException("session already exists: " + sessionId);
        SessionDocument created = SessionDocument.empty(sessionId, model, workingDirectory, createdAt);
        writeNew(target, created);
        return created;
    }

    @Override
    public synchronized Optional<SessionDocument> load(String sessionId) {
        Path target = path(sessionId);
        if (!Files.exists(target)) return Optional.empty();
        try {
            SessionDocument latest = null;
            long expectedRevision = 0;
            for (String line : Files.readAllLines(target, StandardCharsets.UTF_8)) {
                if (line.isBlank()) continue;
                SessionDocument decoded;
                try {
                    JsonNode envelope = lines.readTree(line);
                    if (envelope.path("formatVersion").asInt() != 1 || !envelope.has("document")) {
                        throw new IllegalStateException("unsupported JSONL Session envelope");
                    }
                    decoded = codec.decode(lines.writeValueAsBytes(envelope.get("document")));
                } catch (RuntimeException | IOException malformed) {
                    throw storage("invalid JSONL Session revision in " + target.getFileName(), malformed);
                }
                if (!decoded.metadata().sessionId().equals(sessionId) || decoded.revision() != expectedRevision++) {
                    throw new IllegalStateException("JSONL Session revision chain is invalid");
                }
                latest = decoded;
            }
            if (latest == null) throw new IllegalStateException("JSONL Session has no committed revision");
            return Optional.of(latest);
        } catch (IOException exception) {
            throw storage("cannot read JSONL Session", exception);
        }
    }

    @Override
    public synchronized List<SessionDocument.Metadata> list() {
        try (var files = Files.list(root)) {
            var result = new ArrayList<SessionDocument.Metadata>();
            for (Path file : files.filter(candidate -> candidate.getFileName().toString().endsWith(SUFFIX)).toList()) {
                String name = file.getFileName().toString();
                load(name.substring(0, name.length() - SUFFIX.length())).map(SessionDocument::metadata).ifPresent(result::add);
            }
            return result.stream().sorted(Comparator.comparing(SessionDocument.Metadata::createdAt).reversed()).toList();
        } catch (IOException exception) {
            throw storage("cannot list JSONL Sessions", exception);
        }
    }

    @Override
    public synchronized SessionDocument update(String sessionId, long expectedRevision,
                                               UnaryOperator<SessionDocument> transition) {
        SessionDocument current = require(sessionId, expectedRevision);
        SessionDocument next = transition.apply(current);
        requireSuccessor(current, next);
        append(path(sessionId), next);
        return next;
    }

    @Override
    public synchronized SessionDocument fork(String sourceSessionId, String newSessionId, String lane,
                                             Optional<String> targetEntryId, SessionDocument.ForkPosition position,
                                             Instant createdAt, long expectedSourceRevision) {
        if (Files.exists(path(newSessionId))) throw new IllegalStateException("session already exists: " + newSessionId);
        SessionDocument source = require(sourceSessionId, expectedSourceRevision);
        SessionDocument fork = source.fork(newSessionId, lane, targetEntryId, position, createdAt);
        writeNew(path(newSessionId), fork);
        return fork;
    }

    @Override
    public synchronized void delete(String sessionId, long expectedRevision) {
        Optional<SessionDocument> current = load(sessionId);
        if (current.isEmpty()) return;
        requireRevision(current.orElseThrow(), expectedRevision);
        try {
            Files.delete(path(sessionId));
        } catch (IOException exception) {
            throw storage("cannot delete JSONL Session", exception);
        }
    }

    private void writeNew(Path target, SessionDocument document) {
        Path temporary = target.resolveSibling(target.getFileName() + ".tmp");
        byte[] encoded = envelope(document);
        try (FileChannel channel = FileChannel.open(temporary, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
            channel.write(ByteBuffer.wrap(encoded));
            channel.force(true);
        } catch (IOException exception) {
            throw storage("cannot write JSONL Session", exception);
        }
        try {
            Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException exception) {
            try { Files.deleteIfExists(temporary); } catch (IOException ignored) { }
            throw storage("cannot publish JSONL Session", exception);
        }
    }

    private void append(Path target, SessionDocument document) {
        byte[] encoded = envelope(document);
        try (FileChannel channel = FileChannel.open(target, StandardOpenOption.WRITE, StandardOpenOption.APPEND)) {
            channel.write(ByteBuffer.wrap(encoded));
            channel.force(true);
        } catch (IOException exception) {
            throw storage("cannot append JSONL Session", exception);
        }
    }

    private byte[] envelope(SessionDocument document) {
        try {
            JsonNode tree = lines.readTree(codec.encode(document));
            byte[] json = lines.writeValueAsBytes(java.util.Map.of("formatVersion", 1, "document", tree));
            byte[] line = java.util.Arrays.copyOf(json, json.length + 1);
            line[line.length - 1] = (byte) '\n';
            return line;
        } catch (IOException exception) {
            throw storage("cannot encode JSONL Session", exception);
        }
    }

    private SessionDocument require(String sessionId, long expectedRevision) {
        SessionDocument current = load(sessionId)
                .orElseThrow(() -> new IllegalStateException("session not found: " + sessionId));
        requireRevision(current, expectedRevision);
        return current;
    }

    private static void requireRevision(SessionDocument current, long expectedRevision) {
        if (current.revision() != expectedRevision) {
            throw new IllegalStateException("session revision conflict: expected " + expectedRevision
                    + ", current " + current.revision());
        }
    }

    private static void requireSuccessor(SessionDocument current, SessionDocument next) {
        if (next == null || !next.metadata().sessionId().equals(current.metadata().sessionId())
                || next.revision() != Math.incrementExact(current.revision())) {
            throw new IllegalStateException("Session transition must preserve identity and advance revision once");
        }
    }

    private Path path(String sessionId) {
        if (sessionId == null || !sessionId.matches("[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?")) {
            throw new IllegalArgumentException("invalid session id");
        }
        Path target = root.resolve(sessionId + SUFFIX).normalize();
        if (!target.getParent().equals(root)) throw new IllegalArgumentException("session path escapes root");
        return target;
    }

    private static IllegalStateException storage(String message, Exception cause) {
        return new IllegalStateException(message, cause);
    }
}
